-- ~/.config/hypr/conf/input.lua
-- Normally you do not edit this file: SUPER + I > Input changes everything here and saves it in
--   ~/.local/state/krmv-setup/input.conf   (key=value lines)   which is read at every login.
-- Keyboard layouts live in ~/.local/state/krmv-setup/layouts (one line, e.g. "us,ru"); right-click the keyboard chip in the bar.
local home = os.getenv("HOME") or ""

-- defaults
local c = {
  mouse_sens = 0, mouse_accel = "adaptive", mouse_natural = false, mouse_scroll = 1, left_handed = false,
  tp_natural = true, tp_tap = true, tp_dwt = true, tp_scroll = 0.5,
}
local f = io.open(home .. "/.local/state/krmv-setup/input.conf", "r")
if f then
  for line in f:lines() do
    local k, v = line:match("^([%w_]+)=(.*)$")
    if k and c[k] ~= nil then
      if type(c[k]) == "boolean" then c[k] = (v == "true")
      elseif type(c[k]) == "number" then c[k] = tonumber(v) or c[k]
      elseif v == "adaptive" or v == "flat" then c[k] = v end
    end
  end
  f:close()
end

local layouts = "us,ru"
local switch  = "grp:alt_shift_toggle"        -- ALT + SHIFT switches the layout
local lf = io.open(home .. "/.local/state/krmv-setup/layouts", "r")
if lf then
  local line = lf:read("*l")
  lf:close()
  if line and line:match("^[%w_,%-]+$") then layouts = line end
end

hl.config({
  input = {
    kb_layout  = layouts,
    kb_options = switch,
    sensitivity    = c.mouse_sens,        -- -1 (slowest) ... 1 (fastest)
    accel_profile  = c.mouse_accel,       -- "adaptive" or "flat"
    natural_scroll = c.mouse_natural,     -- regular USB mouse
    scroll_factor  = c.mouse_scroll,
    left_handed    = c.left_handed,
    touchpad = {
      natural_scroll       = c.tp_natural,
      tap_to_click         = c.tp_tap,
      disable_while_typing = c.tp_dwt,
      scroll_factor        = c.tp_scroll, -- trackpad scroll speed (1.0 = default, lower = slower)
    },
  },
})
